(window.CONTENT_LOADED=window.CONTENT_LOADED||{})["usluga/dzierzawa-oze"]={"h1Full":"Dzierżawa pod fotowoltaikę i wiatraki: umowa po stronie właściciela gruntu","topic":"Dzierżawa pod OZE","subtitle":"Firma OZE chce wydzierżawić Twoją ziemię pod farmę fotowoltaiczną albo wiatraki i przysłała gotową umowę? Dzierżawa ziemi pod fotowoltaikę to zwykle umowa na 25–30 lat. Sprawdzam i negocjuję taką umowę po stronie właściciela gruntu.","short":{"q":"Na co uważać w umowie dzierżawy ziemi pod fotowoltaikę?","a":"Przede wszystkim na czas trwania, czynsz przed budową, waloryzację, przeniesienie umowy, podatek od gruntu i zwrot gruntu. Kodeks reguluje je ogólnie, a zwrot gruntu wprost zostawia umowie (art. 705 k.c.: „w braku odmiennej umowy”).","facts":[["Umowa na ponad 30 lat","Po 30 latach poczytuje się ją za zawartą na czas nieoznaczony (art. 695 § 1 k.c.)"],["Waloryzacja czynszu","Zapisujesz ją w umowie; bez niej co do zasady płaci się kwotę nominalną (art. 358¹ § 1 i 2 k.c.)"],["Przeniesienie umowy","Przejęcie obowiązku płacenia czynszu przez inną spółkę i poddzierżawa wymagają Twojej zgody (art. 519 § 2, art. 698 § 1 k.c.)"],["Podatek od gruntu pod farmą","Podatnikiem jest właściciel, chyba że grunt ma posiadacz samoistny (art. 3 ust. 1 pkt 1 i ust. 3 u.p.o.l.); inwestor oddaje Ci ten podatek, jeżeli umowa tak stanowi (art. 702 k.c.)"],["Szkoda na gruncie po zwrocie","Rok od dnia zwrotu gruntu na roszczenie o naprawienie szkody z powodu jego pogorszenia (art. 677 w zw. z art. 694 k.c.)"]]},"introHeading":"Co podpisujesz, gdy oddajesz ziemię pod farmę","intro":"Umowa pod panele albo turbiny wiatrowe zobowiązuje Cię oddać grunt inwestorowi, a jego do płacenia umówionego czynszu (art. 693 k.c.). Przy turbinach Sąd Najwyższy uznał ją za umowę nienazwaną, do której przepisy o dzierżawie stosuje się odpowiednio (wyrok z 5.10.2012, IV CSK 244/12). Farma fotowoltaiczna na użytkach rolnych klas I–III, na klasie IV (ponad 150 kW albo przy działalności gospodarczej w zakresie wytwarzania energii) oraz na innych gruntach przy mocy ponad 1000 kW może powstać tylko na podstawie planu miejscowego (art. 14 ust. 6a pkt 2 u.p.z.p.). Turbina wiatrowa wymaga planu miejscowego zawsze (art. 3 ustawy o inwestycjach w zakresie elektrowni wiatrowych). Inwestor zwykle podpisuje umowę, zanim ma decyzje potrzebne do budowy, więc grunt bywa związany umową przez cały okres przygotowawczy.","whenTitle":"Czy to Twoja sytuacja","whenHeading":"Firma OZE chce dzierżawić Twoją ziemię","when":[{"b":"Inwestor przysłał umowę do podpisu i naciska na szybki termin.","t":"Poprawki najprościej wprowadzić przed podpisem. Później każda zmiana wymaga zgody inwestora i co najmniej formy pisemnej (art. 77 § 1, art. 660 w zw. z art. 694 k.c.)."},{"b":"W umowie jest zgoda na przeniesienie umowy na spółkę celową albo na bank.","t":"Zgoda wpisana z góry dotyczy dzierżawcy, którego dziś nie znasz."},{"b":"Inwestor chce wpisać dzierżawę do księgi wieczystej.","t":"Po wpisie dzierżawa działa także wobec osoby, która później kupi Twoją działkę, bo wiąże prawa nabyte przez czynność prawną po ujawnieniu (art. 16 ust. 2 pkt 1, art. 17 u.k.w.h.)."},{"b":"Martwisz się, kto po 29 latach usunie panele albo turbiny, fundamenty i kable.","t":"O zakresie demontażu decyduje umowa, bo kodeksowy obowiązek zwrotu gruntu działa „w braku odmiennej umowy” (art. 705 k.c.)."}],"lists":[{"eyebrow":"Przed podpisem","title":"Zapisy, które sprawdzam w każdej umowie pod farmę","kind":"check","items":[{"b":"Okres przygotowawczy","t":"ryzyko: grunt związany umową bez czynszu albo za symboliczną kwotę. Negocjuję czynsz za ten czas i datę graniczną budowy, po której możesz wypowiedzieć umowę."},{"b":"Waloryzacja","t":"ryzyko: kwota z pierwszego roku obowiązuje do końca. Negocjuję coroczną waloryzację według wskaźnika z umowy."},{"b":"Przeniesienie umowy","t":"ryzyko: zgoda na dowolny podmiot. Negocjuję zgodę tylko na wskazane podmioty i odpowiedzialność pierwszego dzierżawcy za czynsz."},{"b":"Wyjście inwestora","t":"ryzyko: odstąpienie w każdej chwili i bez kosztów. Negocjuję termin odstąpienia (art. 395 § 1 k.c.) albo odstępne (art. 396 k.c.)."},{"b":"Demontaż","t":"ryzyko: brak zapisu o fundamentach, kablach i drogach. Negocjuję demontaż na koszt inwestora, termin i zabezpieczenie finansowe, np. gwarancję bankową."}]}],"doForTitle":"Co robię przy umowie z inwestorem OZE","doFor":["Sprawdzam w KRS spółkę, która ma zostać dzierżawcą, a w wypisie z rejestru gruntów klasy użytków.","Sprawdzam datę zakupu ziemi: przez 5 lat od nabycia oddanie jej w posiadanie co do zasady wymaga zgody Dyrektora Generalnego KOWR (art. 2b ust. 2–3 u.k.u.r.).","Przygotowuję protokół wydania gruntu ze stanem pola, dróg i rowów, do porównania przy zwrocie.","Dopisuję podstawy wypowiedzenia szersze niż zwłoka z czynszem (art. 703 k.c.), np. brak zabezpieczenia demontażu w terminie."],"stepsHeading":"Od propozycji inwestora do podpisanej umowy dzierżawy","steps":["Przesyłasz projekt umowy od firmy OZE. W 24 h roboczych odpisuję, czy umowę wystarczy sprawdzić, czy trzeba ją negocjować, i wysyłam ofertę z ceną oraz terminem. Oceny poszczególnych zapisów ta odpowiedź jeszcze nie zawiera.","Po akceptacji dostajesz tabelę: zapis inwestora, ryzyko, proponowane brzmienie. Wybierasz, które zmiany zgłaszamy.","Wysyłam inwestorowi tabelę zmian i prowadzę rundy uzgodnień. Nie obiecuję, że przyjmie każdą zmianę; mówię, które zapisy uważam za warunek podpisu.","Podpisujesz na piśmie ostatnią uzgodnioną wersję (art. 660 w zw. z art. 694 k.c.). Od tej chwili zapisy zmienisz tylko aneksem, na który musi zgodzić się inwestor."],"faq":[{"q":"Ile płacą za hektar pod farmę fotowoltaiczną?","a":"Nie ma stawki ustawowej: czynsz ustalasz z inwestorem w umowie (art. 693 § 1–2 k.c.). Porównując oferty, sprawdź czynsz za hektar rocznie, kwotę przed budową i waloryzację. Te trzy liczby zestawiam w tabeli zmian."},{"q":"Kto zapłaci podatek od nieruchomości za grunt pod farmą?","a":"Co do zasady Ty jako właściciel gruntu, a nie inwestor (art. 3 ust. 1 pkt 1 u.p.o.l.). Jeżeli inwestor ma Ci ten podatek oddawać, zapisz to w umowie (art. 702 k.c.). Użytki rolne zajęte na prowadzenie działalności gospodarczej podlegają podatkowi od nieruchomości (art. 2 ust. 2 u.p.o.l.). Wysokość podatku i VAT od czynszu oceni doradca podatkowy."},{"q":"Co jeśli inwestor nie dostanie pozwoleń – czy płaci cokolwiek?","a":"Tyle, ile zapisano w umowie na okres przed budową. Umowne prawo odstąpienia można zastrzec tylko na oznaczony termin (art. 395 § 1 k.c.). Przy odstępnym odstąpienie działa dopiero razem z zapłatą (art. 396 k.c.). Dlatego negocjuję czynsz za czas oczekiwania i datę graniczną budowy."},{"q":"Czy do czasu budowy mogę dalej uprawiać ziemię?","a":"Tak, jeżeli umowa wiąże wydanie gruntu z rozpoczęciem budowy, a nie z dniem podpisu. Gdy termin wydania nie wynika z umowy, inwestor może co do zasady żądać gruntu niezwłocznie po wezwaniu (art. 455 k.c.). Dlatego wpisuję, że uprawiasz pole do dnia wydania potwierdzonego protokołem."},{"q":"Kto usunie panele albo turbiny po 29 latach?","a":"Ten, kogo wskaże umowa. Kodeksowy obowiązek zwrotu gruntu działa tylko „w braku odmiennej umowy” (art. 705 k.c.). Stan gruntu spisz w protokole przy odbiorze. Masz rok od zwrotu, żeby dochodzić naprawienia szkody za pogorszenie gruntu; potem roszczenie się przedawnia (art. 677 w zw. z art. 694 k.c.)."}],"law":{"asOf":"2026-10-10","items":[{"ref":"art. 693–705","act":"Ustawa z dnia 23 kwietnia 1964 r. – Kodeks cywilny","tj":"Dz.U. 2026 poz. 795","eli":"DU/1964/93","note":"Dzierżawa: czynsz, 30 lat, poddzierżawa, podatki, zwrot gruntu."},{"ref":"art. 77, 358¹, 395, 396, 455, 519, 660, 677","act":"Ustawa z dnia 23 kwietnia 1964 r. – Kodeks cywilny","tj":"Dz.U. 2026 poz. 795","eli":"DU/1964/93","note":"Forma, waloryzacja, odstąpienie, wydanie gruntu, przejęcie długu."},{"ref":"art. 2 ust. 2, art. 3 ust. 1","act":"Ustawa z dnia 12 stycznia 1991 r. o podatkach i opłatach lokalnych","tj":"Dz.U. 2025 poz. 707","eli":"DU/1991/31","note":"Kto płaci podatek od nieruchomości."},{"ref":"art. 14 ust. 6a","act":"Ustawa z dnia 27 marca 2003 r. o planowaniu i zagospodarowaniu przestrzennym","tj":"Dz.U. 2026 poz. 538","eli":"DU/2003/717","note":"Kiedy farma wymaga planu miejscowego."},{"ref":"art. 16 ust. 2 pkt 1, art. 17","act":"Ustawa z dnia 6 lipca 1982 r. o księgach wieczystych i hipotece","tj":"Dz.U. 2026 poz. 1066","eli":"DU/1982/147","note":"Wpis dzierżawy do księgi wieczystej."},{"ref":"art. 2b ust. 2–4","act":"Ustawa z dnia 11 kwietnia 2003 r. o kształtowaniu ustroju rolnego","tj":"Dz.U. 2026 poz. 941","eli":"DU/2003/592","note":"Zgoda KOWR przed upływem 5 lat od zakupu."},{"ref":"art. 3","act":"Ustawa z dnia 20 maja 2016 r. o inwestycjach w zakresie elektrowni wiatrowych","tj":"Dz.U. 2024 poz. 317","eli":"DU/2016/961","note":"Turbina tylko na podstawie planu miejscowego."}]},"docs":["Projekt umowy dzierżawy albo umowy przedwstępnej od firmy OZE","Oferta albo list intencyjny inwestora, jeśli są","Wypis z rejestru gruntów z klasami użytków, jeśli masz","Numer księgi wieczystej działki, jeśli masz","Akt notarialny zakupu ziemi, jeśli kupiłeś ją w ostatnich 5 latach","Mapa z zaznaczonym terenem farmy, jeśli inwestor ją przysłał"],"seeAlso":["negocjacje-nieruchomosci","plan-ogolny","obsluga-prawna-deweloperow-oze"],"cta":{"heading":"Twój grunt na 30 lat — podpisz dopiero, gdy umowa naprawdę Cię chroni.","lead":"Prześlij projekt umowy od firmy OZE. W 24 h roboczych dostaniesz informację, jakiego zakresu pracy wymaga Twoja umowa, i ofertę z ceną i terminem; do jej akceptacji nic nie płacisz."}};
